DROP TABLE IF EXISTS audit_log; DROP TABLE IF EXISTS onboarding_tasks; DROP TABLE IF EXISTS approvals; DROP TABLE IF EXISTS access_requests; DROP TABLE IF EXISTS tickets; DROP TABLE IF EXISTS assets; DROP TABLE IF EXISTS software_subscriptions; DROP TABLE IF EXISTS contracts; DROP TABLE IF EXISTS systems; DROP TABLE IF EXISTS vendors; DROP TABLE IF EXISTS employees; DROP TABLE IF EXISTS departments; DROP TABLE IF EXISTS user_groups;
CREATE TABLE user_groups (user_group_id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT NOT NULL);
CREATE TABLE departments (department_id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, default_manager_id TEXT);
CREATE TABLE employees (employee_id TEXT PRIMARY KEY, full_name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, department_id TEXT NOT NULL, role TEXT NOT NULL, manager_id TEXT, location TEXT NOT NULL, employment_type TEXT NOT NULL, status TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, user_group_id TEXT NOT NULL, systems_allowed_by_role TEXT NOT NULL, notes TEXT);
CREATE TABLE vendors (vendor_id TEXT PRIMARY KEY, vendor_name TEXT NOT NULL UNIQUE, primary_system_name TEXT NOT NULL, category TEXT NOT NULL, notes TEXT);
CREATE TABLE systems (system_id TEXT PRIMARY KEY, system_name TEXT NOT NULL UNIQUE, vendor_id TEXT NOT NULL, category TEXT NOT NULL, data_sensitivity TEXT NOT NULL, default_owner_department TEXT NOT NULL, requires_mfa INTEGER NOT NULL);
CREATE TABLE contracts (contract_id TEXT PRIMARY KEY, vendor_id TEXT NOT NULL, system_id TEXT NOT NULL, contract_name TEXT NOT NULL, document_path TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, renewal_type TEXT NOT NULL, renewal_notice_days INTEGER NOT NULL, annual_cost INTEGER NOT NULL, owner_department_id TEXT NOT NULL, status TEXT NOT NULL, security_review_required INTEGER NOT NULL);
CREATE TABLE software_subscriptions (subscription_id TEXT PRIMARY KEY, system_id TEXT NOT NULL, vendor_id TEXT NOT NULL, contract_id TEXT NOT NULL, seat_limit INTEGER NOT NULL, active_seats INTEGER NOT NULL, renewal_date TEXT NOT NULL, status TEXT NOT NULL, owner_department_id TEXT NOT NULL, annual_cost INTEGER NOT NULL);
CREATE TABLE assets (asset_id TEXT PRIMARY KEY, employee_id TEXT, asset_type TEXT NOT NULL, model TEXT NOT NULL, status TEXT NOT NULL, location TEXT NOT NULL, assigned_at TEXT, notes TEXT);
CREATE TABLE tickets (ticket_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL, category TEXT NOT NULL, subcategory TEXT NOT NULL, priority TEXT NOT NULL, status TEXT NOT NULL, subject TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, assigned_team TEXT NOT NULL, related_system_id TEXT);
CREATE TABLE access_requests (request_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL, system_id TEXT NOT NULL, access_level TEXT NOT NULL, business_justification TEXT NOT NULL, status TEXT NOT NULL, approver_id TEXT, created_at TEXT NOT NULL, decision_reason TEXT);
CREATE TABLE approvals (approval_id TEXT PRIMARY KEY, request_type TEXT NOT NULL, request_id TEXT NOT NULL, approver_id TEXT NOT NULL, status TEXT NOT NULL, decision_reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE onboarding_tasks (task_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL, task_type TEXT NOT NULL, description TEXT NOT NULL, owner_group TEXT NOT NULL, status TEXT NOT NULL, due_date TEXT NOT NULL, related_system_id TEXT);
CREATE TABLE audit_log (event_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, event_type TEXT NOT NULL, actor_employee_id TEXT, created_at TEXT NOT NULL, notes TEXT);
